-- 2. Insert New Fragrances (Duplicate check via ON CONFLICT)
INSERT INTO perfumes (id, brand_id, name, gender, concentration, price, volume_ml, in_stock, is_dupe_of, description_ar, description_fr, description_en) VALUES
-- 1. Dossier Woody Green Apple
('90000000-0000-0000-0000-000000000011', 'b0000000-0000-0000-0000-000000000006', 'Woody Green Apple', 'male', 'edp', 0, 50, true, 'Paco Rabanne 1 Million', 'تركيبة منعشة وفاكهية خشبية تجمع بين التفاح الأخضر والنعناع مع القرفة والباتشولي والبرغموت.', 'Un parfum frais fruité et boisé alliant pomme verte, menthe et cannelle.', 'A fresh, woody, and fruity blend of green apple, crisp mint, warm cinnamon, and patchouli.'),
-- 2. Palermo Inspired 1 Million Royal
('90000000-0000-0000-0000-000000000012', 'b0000000-0000-0000-0000-000000000007', 'Inspired By 1 Million Royal', 'male', 'parfum', 0, 50, true, 'Paco Rabanne 1 Million Royal', 'تركيبة زيتية بتركيز عالي مستوحاة من رويال فلانكر بمزيج الهيل واليوسفي واللافندر وقاعدة الأرز والجاوي.', 'Mélange huileux concentré de cardamome, mandarine, lavande et cèdre.', 'High-concentration clone featuring cardamom, fresh tangerine, soothing lavender, and cedarwood.'),
-- 3. ShyGuy 1 Million Royal Oil
('90000000-0000-0000-0000-000000000013', 'b0000000-0000-0000-0000-000000000008', '1 Million Royal Inspired Perfume Oil', 'male', 'parfum', 0, 15, true, 'Paco Rabanne 1 Million Royal', 'زيت عطري نقي 100% خالي من الكحول يتميز بنوتات الهيل والبرغموت واللافندر مع الجاوي والباتشولي.', 'Huile de parfum pure sans alcool de cardamome, lavande et patchouli.', '100% pure alcohol-free perfume oil alternative containing cardamom, lavender, and patchouli.'),
-- 4. Voyageur 1 Million Royal Type
('90000000-0000-0000-0000-000000000014', 'b0000000-0000-0000-0000-000000000009', '1 Million Royal Fragrance Oil Type', 'unisex', 'parfum', 0, 30, true, 'Paco Rabanne 1 Million Royal', 'زيت عطري مركز مخصص للتصنيع والتركيب الفوري مستوحى من نوتات رويال الحارة والخشبية.', 'Huile parfumée concentrée de type Royal pour compositions fraîches.', 'Highly concentrated custom product formulation oil inspired by the Royal profile.'),
-- 5. Lattafa Asad
('90000000-0000-0000-0000-000000000015', 'b0000000-0000-0000-0000-000000000010', 'Asad', 'male', 'edp', 0, 100, true, 'Dior Sauvage Elixir', 'عطر شرقي دافئ توابلي يجمع بين الفلفل الأسود والتبغ والقهوة والباتشولي مع حلاوة الفانيليا واللابدانوم.', 'Un parfum oriental épicé chaud combinant le poivre, le tabac, le café et la vanille.', 'A warm spicy oriental scent known for black pepper, rich tobacco, coffee, vanilla, and labdanum.'),
-- 6. Masa by Kajal
('90000000-0000-0000-0000-000000000016', 'b0000000-0000-0000-0000-000000000011', 'Masa', 'unisex', 'edp', 0, 100, true, NULL, 'عطر نيش متوازن يجمع بين انتعاش الجريب فروت والزنجبيل والتوابل مع عمق خشب الغاياك والباتشولي والفانيليا.', 'Un parfum de niche hespéridé et épicé avec du gingembre, cardamome et bois de gaïac.', 'A balanced niche option offering grapefruit, spicy ginger, cardamom, guaiac wood, and patchouli.'),
-- 7. Azzaro The Most Wanted Parfum
('90000000-0000-0000-0000-000000000017', 'b0000000-0000-0000-0000-000000000012', 'The Most Wanted', 'male', 'parfum', 0, 100, true, NULL, 'عطر خشبي غورماند دافئ ومثير بمزيج الزنجبيل الأحمر والأخشاب مع الكراميل الحلو والفانيليا.', 'Un boisé gourmand intense avec du gingembre rouge, du caramel et de la vanille.', 'An intensely sweet and woody blend combining red ginger, warm caramel, and rich vanilla.'),
-- 8. Tonka Lavande by Marie Jeanne
('90000000-0000-0000-0000-000000000018', 'b0000000-0000-0000-0000-000000000013', 'Tonka Lavande', 'unisex', 'edp', 0, 100, true, NULL, 'عطر فوجير كلاسيكي حديث يلعب على نوتات الخزامى المهدئة والميرمية مع فول التونكا الدافئ.', 'Un parfum fougère moderne de lavande, sauge et fève tonka.', 'A modern fougere scent focused on soothing lavender, herbal sage, and sweet tonka bean.'),
-- 9. Paco Rabanne Invictus
('90000000-0000-0000-0000-000000000019', 'b0000000-0000-0000-0000-000000000014', 'Invictus', 'male', 'edt', 0, 100, true, NULL, 'انتعاش الجريب فروت والنوتات البحرية مع أخشاب الغاياك والباتشولي وطحلب البلوط والياسمين.', 'Fraîcheur de pamplemousse et notes marines avec patchouli et bois de gaïac.', 'A fresh marine scent pairing grapefruit and sea notes with guaiac wood, oakmoss, and patchouli.'),
-- 10. JPG Le Male
('90000000-0000-0000-0000-000000000020', 'b0000000-0000-0000-0000-000000000015', 'Le Male', 'male', 'edt', 0, 125, true, NULL, 'مزيج كلاسيكي دافئ من النعناع واللافندر والبرغموت مع القرفة والهيل والفانيليا وخشب الصندل والتونكا.', 'Menthe fraîche et lavande avec de la cannelle, de la vanille et du santal.', 'A classic warm fougere featuring cooling mint, lavender, cinnamon, sandalwood, and sweet vanilla.'),
-- 11. Giorgio Armani Acqua di Gio
('90000000-0000-0000-0000-000000000021', 'b0000000-0000-0000-0000-000000000016', 'Acqua di Gio', 'male', 'edt', 0, 100, true, NULL, 'انتعاش البحر الأبيض المتوسط بمزيج البرغموت والنيرولي والنوتات البحرية مع الياسمين وإكليل الجبل وقاعدة المسك والأرز.', 'Notes marines, bergamote et néroli avec du jasmin, du romarin et du cèdre.', 'An iconic aquatic blend of bergamot, neroli, sea notes, jasmine, rosemary, and white musk.'),
-- 12. Versace Eros
('90000000-0000-0000-0000-000000000022', 'b0000000-0000-0000-0000-000000000017', 'Eros', 'male', 'edt', 0, 100, true, NULL, 'انتعاش النعناع والتفاح الأخضر والليمون مع دفء التونكا والأمبروكسان والفانيليا والأرز ونجيل الهند.', 'Menthe fraîche, pomme verte et citron avec fève tonka, vanille et cèdre.', 'Fresh mint, green apple, and lemon layered with sweet tonka bean, ambergris, and vanilla.'),
-- 13. Viktor & Rolf Spicebomb
('90000000-0000-0000-0000-000000000023', 'b0000000-0000-0000-0000-000000000018', 'Spicebomb', 'male', 'edt', 0, 90, true, NULL, 'عطر توابلي متفجر بمزيج الفلفل والبرغموت والقرفة والزعفران مع أوراق التبغ والجلد الفاخر ونجيل الهند.', 'Un parfum épicé explosif de piment, cannelle, safran, tabac et cuir.', 'A warm spicy explosion of black pepper, cinnamon, saffron, tobacco, and leather.'),
-- 14. Giorgio Armani Stronger with You
('90000000-0000-0000-0000-000000000024', 'b0000000-0000-0000-0000-000000000016', 'Stronger with You', 'male', 'edt', 0, 100, true, NULL, 'عطر دافئ وجذاب بمزيج الهيل والفلفل الوردي مع أوراق الميرمية واللافندر والفانيليا الكثيفة والعنبر.', 'Cardamome, poivre rose et sauge avec une base riche de vanille et d''ambre.', 'A sweet aromatic spicy blend of cardamom, sage, lavender, vanilla, and amber.'),
-- 15. YSL Y
('90000000-0000-0000-0000-000000000025', 'b0000000-0000-0000-0000-000000000019', 'Y', 'male', 'edp', 0, 100, true, NULL, 'عطر أزرق منعش وقوي يجمع بين البرغموت والزنجبيل والتفاح مع الميرمية والأرز والأمبروكسان والتونكا.', 'Bergamote, gingembre et pomme avec sauge, cèdre et fève tonka.', 'A modern fresh blue scent containing bergamot, ginger, green apple, sage, and cedarwood.'),
-- 16. Dior Fahrenheit
('90000000-0000-0000-0000-000000000026', 'b2000000-0000-0000-0000-000000000002', 'Fahrenheit', 'male', 'edt', 0, 100, true, NULL, 'العطر الرجالي الأيقوني بمزيج اليوسفي واللافندر والبنفسج وخشب الصندل وقاعدة دافئة من الجلد والباتشولي والمسك.', 'Un parfum iconique de mandarine, violette, cuir, patchouli et musc.', 'A unique legendary masculine signature blending mandarin, lavender, violet, leather, and patchouli.'),
-- 17. Carolina Herrera Good Girl
('90000000-0000-0000-0000-000000000027', 'b0000000-0000-0000-0000-000000000020', 'Good Girl', 'female', 'edp', 0, 80, true, NULL, 'عطر شرقي زهري حسي يجمع بين اللوز والقهوة والبرغموت مع الياسمين ومسك الروم والكاكاو وفول التونكا والفانيليا.', 'Amande, café et bergamote avec jasmin, tubéreuse, cacao et fève tonka.', 'A sweet oriental floral combining almond, coffee, jasmine, tuberose, rich cocoa, and vanilla.'),
-- 18. YSL Black Opium
('90000000-0000-0000-0000-000000000028', 'b0000000-0000-0000-0000-000000000019', 'Black Opium', 'female', 'edp', 0, 90, true, NULL, 'مزيج دافئ ومغرٍ من الفلفل الوردي والقهوة الغنية مع الياسمين الفواح والفانيليا الكريمية والباتشولي والأرز.', 'Café noir, jasmin et poivre rose avec de la vanille et du patchouli.', 'An addictive warm gourmand highlighting dark coffee, jasmine, vanilla, and patchouli.'),
-- 19. Chanel Coco Mademoiselle
('90000000-0000-0000-0000-000000000029', 'b1000000-0000-0000-0000-000000000001', 'Coco Mademoiselle', 'female', 'edp', 0, 100, true, NULL, 'باقة زهرية منعشة وراقية تمزج البرغموت والبرتقال مع الورد والياسمين والباتشولي ونجيل الهند والمسك.', 'Orange, bergamote et rose avec du jasmin, du patchouli et du vétiver.', 'A classic sophisticated floral combining fresh orange, rose, jasmine, patchouli, and vetiver.'),
-- 20. Lancôme La Vie Est Belle
('90000000-0000-0000-0000-000000000030', 'b0000000-0000-0000-0000-000000000021', 'La Vie Est Belle', 'female', 'edp', 0, 75, true, NULL, 'عطر أنثوي غني وحلو بمزيج الكشمش الأسود والكمثرى مع الياسمين وزهور السوسن والبرالين المقرمش والفانيليا والباتشولي.', 'Poire, cassis et jasmin avec praliné, vanille et patchouli.', 'A cheerful sweet gourmand combining blackcurrant, pear, jasmine, praline, and vanilla.'),
-- 21. Maison Francis Kurkdjian Baccarat Rouge 540
('90000000-0000-0000-0000-000000000031', 'b0000000-0000-0000-0000-000000000022', 'Baccarat Rouge 540', 'unisex', 'edp', 0, 70, true, NULL, 'العطر الأكثر شهرة بمزيج الزعفران والياسمين والعمق البلسمي للأمبروكسان وخشب الأرز والمسك.', 'Un accord de safran, jasmin et ambre avec du bois de cèdre.', 'An ultra-popular signature scent blending saffron, jasmine, warm amberwood, and cedarwood.'),
-- 22. Viktor & Rolf Flowerbomb
('90000000-0000-0000-0000-000000000032', 'b0000000-0000-0000-0000-000000000018', 'Flowerbomb', 'female', 'edp', 0, 100, true, NULL, 'باقة زهرية متفجرة من الياسمين والفريزيا والأوركيد مع انتعاش البرغموت والشاي وقاعدة غنية من الباتشولي والمسك والفانيليا.', 'Thé vert et bergamote avec jasmin, freesia, patchouli et vanille.', 'An explosive floral bouquet of tea, bergamot, jasmine, orchid, patchouli, and vanilla.'),
-- 23. Victoria's Secret Bombshell
('90000000-0000-0000-0000-000000000033', 'b0000000-0000-0000-0000-000000000023', 'Bombshell', 'female', 'edp', 0, 100, true, NULL, 'عطر فاكهي زهري مشرق بمزيج الكمثرى والفاكهة الاستوائية مع الفاوانيا والأوركيد والمسك والأخشاب الناعمة.', 'Poire et pivoine avec de l''orchidée et du musc propre.', 'A bright fruity-floral scent featuring pear, peony, orchid, white musk, and soft cedarwood.'),
-- 24. Parfums de Marly Delina
('90000000-0000-0000-0000-000000000034', 'b0000000-0000-0000-0000-000000000024', 'Delina', 'female', 'edp', 0, 75, true, NULL, 'عطر نيش أنثوي فاخر برائحة الورد التركي والفاوانيا مع لمسات حمضية منعشة من البرغموت والكمثرى وقاعدة من الفانيليا والأرز والمسك.', 'Rose turque, pivoine, litchi, bergamote et vanille.', 'A luxurious niche floral highlighted by Turkish rose, peony, fresh bergamot, cedar, and vanilla.'),
-- 25. Dolce & Gabbana Light Blue
('90000000-0000-0000-0000-000000000035', 'b0000000-0000-0000-0000-000000000025', 'Light Blue', 'female', 'edt', 0, 100, true, NULL, 'انتعاش صيف إيطاليا بمزيج الليمون الصقلي والتفاح الأخضر مع الياسمين وخشب الأرز والعنبر والمسك.', 'Citron de Sicile, pomme verte et jasmin avec cèdre, ambre et musc.', 'A fresh summer classic combining Sicilian lemon, green apple, jasmine, cedarwood, and musk.'),
-- 26. Nasomatto Black Afgano
('90000000-0000-0000-0000-000000000036', 'b0000000-0000-0000-0000-000000000026', 'Black Afgano', 'unisex', 'parfum', 0, 30, true, NULL, 'عطر نيش غامض وداكن ومثير يبرز نوتات القهوة الغنية مع العود والجلد والبخور الراتنجي الدافئ.', 'Café noir et oud précieux avec de l''encens et du cuir.', 'A dark, resinous, and smoky niche blend of rich coffee, dark oud, and incense.'),
-- 27. Aroma M Kirke
('90000000-0000-0000-0000-000000000037', 'b0000000-0000-0000-0000-000000000027', 'Kirke', 'unisex', 'parfum', 0, 100, true, NULL, 'عطر شرقي فاكهي ساحر يجمع بين الخوخ الاستوائي والزعفران والياسمين والورد مع العود وخشب الصندل والمسك الأبيض.', 'Pêche, safran et rose avec du jasmin, de l''oud et du musc.', 'A magical fruity-oriental combining peach, saffron, rose, jasmine, oud, and white musk.'),
-- 28. Lattafa Bade''e Al Oud Sahari
('90000000-0000-0000-0000-000000000038', 'b0000000-0000-0000-0000-000000000010', 'Bade''e Al Oud Sahari', 'unisex', 'edp', 0, 100, true, NULL, 'تركيبة شرقية فخمة من الزعفران والورد والعود الفاخر ممزوجة مع العنبر الدافئ والمسك وخشب الصندل.', 'Safran, oud et rose avec de l''ambre, du musc et du santal.', 'A rich oriental blend combining saffron, precious oud, elegant rose, amber, and musk.'),
-- 29. MFK Grand Soir
('90000000-0000-0000-0000-000000000039', 'b0000000-0000-0000-0000-000000000022', 'Grand Soir', 'unisex', 'edp', 0, 70, true, NULL, 'جسد الأناقة الشرقية الدافئة بمزيج العنبر والجاوي واللابدانوم مع حلاوة الفانيليا واللوز وفول التونكا.', 'Ambre chaud, benjoin, labdanum, vanille et fève tonka.', 'A warm amber signature combining benzoin, labdanum, vanilla, and tonka bean.')
ON CONFLICT (id) DO NOTHING;

